func Split(s string, sep rune, field bool) (res []string) {

	if s == "" {
		return nil
	}
	var temp []rune
	for _, r := range s {
		if r == sep {
			res = append(res, string(temp))
			temp = nil
			continue
		}
		temp = append(temp, r)
	}
	res = append(res, string(temp))

	if field {
		temp := res
		res = nil
		for _, str := range temp {
			if str != "" {
				res = append(res, str)
			}
		}
		return res
	}
	return res
}

